// Brand marks, bare (no tile, no tint). Generated from reputable sources, nothing redrawn:
//  - lobehub icons-static-svg 1.95.1 (MIT): AI provider marks, colour variants where they read on both themes
//  - simple-icons 16.35.0 (CC0-1.0): messaging marks, painted in the brand hex from the same package
//  - gilbarbara/logos (CC0-1.0): Slack and Microsoft Teams full-colour marks
// The marks stay the trademarks of their owners; they appear only to say connected to X.
// A brand colour that would not read on the light or the dark surface falls back to the text colour there.
// DingTalk, Feishu/Lark and WeCom have no genuine full-colour SVG in any of these sources; those rows use a neutral glyph.

export interface BrandMark {
  /** Brand hex for single-colour marks. */
  color?: string
  /** null: this brand colour does not read on dark, use the text colour. */
  colorDark?: null
  /** null: this brand colour does not read on light, use the text colour. */
  colorLight?: null
  evenodd?: boolean
  paths?: readonly string[]
  /** Full-colour marks keep their own fills (and gradients) as inner SVG markup. */
  raw?: string
  viewBox: string
}

